def populate_participant_links(apps, schema_editor):
    database = schema_editor.connection.alias
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    Participant = apps.get_model("communication", "CommunicationParticipant")
    Conversation = apps.get_model("communication", "Conversation")
    Message = apps.get_model("communication", "Message")
    Review = apps.get_model("communication", "Review")

    def participant_for(user_id):
        user = User.objects.using(database).get(pk=user_id)
        name = str(user)
        participant, _ = Participant.objects.using(database).get_or_create(
            user_id=user_id,
            defaults={"display_name": name[:80]},
        )
        return participant

    for conversation in Conversation.objects.using(database).all().iterator():
        if conversation.passenger_id:
            conversation.participant_one_id = participant_for(
                conversation.passenger_id
            ).pk
        if conversation.driver_id:
            conversation.participant_two_id = participant_for(
                conversation.driver_id
            ).pk
        if not conversation.invite_code:
            conversation.invite_code = secrets.token_urlsafe(24)
        conversation.save(
            update_fields=["participant_one", "participant_two", "invite_code"]
        )

    for message in Message.objects.using(database).all().iterator():
        if message.sender_id:
            message.sender_participant_id = participant_for(message.sender_id).pk
            message.save(update_fields=["sender_participant"])

    for review in Review.objects.using(database).all().iterator():
        if review.reviewer_id:
            review.reviewer_participant_id = participant_for(review.reviewer_id).pk
        if review.target_id:
            review.target_participant_id = participant_for(review.target_id).pk
        review.save(update_fields=["reviewer_participant", "target_participant"])


